from pathlib import Path
import ast
ROOT = Path(__file__).resolve().parent
PKG = ROOT / 'qseries_v2/oracle_execution/solana_atomic_executor'
TARGET = PKG / 'mtr_144_route_identity_latest_queue.py'
TEST = ROOT / 'test_mtr_144_route_identity_latest_queue.py'
MODULE = '"""MTR-144: route-keyed latest-state queue, isolated from production.\n\nDoes not invoke ORACLE-020 (token-keyed) until per-route pricing is supported.\nInputs are already-warm canonical snapshots from a trusted WS producer.\n"""\nfrom dataclasses import dataclass\nfrom threading import RLock\nfrom types import MappingProxyType\n\nSIZES = (0.010, 0.015, 0.020, 0.025, 0.030)\n\n@dataclass(frozen=True)\nclass RouteKey:\n    token: str\n    pump_pool: str\n    dlmm_pool: str\n\n@dataclass(frozen=True)\nclass Queued:\n    route: RouteKey\n    epoch: int\n    generation: int\n    slot: int\n    received_ns: int\n    snapshot: object\n\nclass RouteLatestQueue:\n    def __init__(self, gate, descriptor):\n        if not callable(getattr(gate, \'current\', None)):\n            raise TypeError(\'admission gate required\')\n        if not callable(descriptor):\n            raise TypeError(\'trusted WS snapshot descriptor required\')\n        self.gate = gate\n        self.describe = descriptor\n        self.lock = RLock()\n        self.latest = {}\n        self.stats = {\'accepted\': 0, \'rejected\': 0, \'replaced\': 0,\n                      \'token_collisions\': 0, \'forwarded\': 0}\n\n    def offer(self, route_id, snapshot, slot, received_ns):\n        # Immutable published admission proof must be current at handoff.\n        with self.lock:\n            proof = self.gate.current(route_id)\n            if proof is None:\n                self.stats[\'rejected\'] += 1\n                return False\n            if type(slot) is not int or slot < 0 or type(received_ns) is not int or received_ns <= 0:\n                raise ValueError(\'invalid slot/time\')\n            x = self.describe(snapshot)\n            if not isinstance(x, dict):\n                raise ValueError(\'snapshot descriptor required\')\n            key = RouteKey(proof.token, proof.pump_pool, proof.dlmm_pool)\n            if (x.get(\'token\'), x.get(\'pump_pool\'), x.get(\'dlmm_pool\')) != (\n                    key.token, key.pump_pool, key.dlmm_pool):\n                raise ValueError(\'route identity mismatch\')\n            if tuple(x.get(\'sizes\', ())) != SIZES:\n                raise ValueError(\'size policy mismatch\')\n            account_slots = x.get(\'account_slots\')\n            if not isinstance(account_slots, dict) or account_slots != dict(proof.snapshot_slots):\n                self.stats[\'rejected\'] += 1\n                return False\n            if not account_slots or slot < max(account_slots.values()):\n                self.stats[\'rejected\'] += 1\n                return False\n            current = self.latest.get(key)\n            new = (proof.epoch, proof.state_generation)\n            if current and new <= (current.epoch, current.generation):\n                self.stats[\'rejected\'] += 1\n                return False\n            if self.gate.current(route_id) != proof:\n                self.stats[\'rejected\'] += 1\n                return False\n            if current:\n                self.stats[\'replaced\'] += 1\n            self.latest[key] = Queued(key, *new, slot, received_ns, snapshot)\n            self.stats[\'accepted\'] += 1\n            return True\n\n    def inventory(self):\n        with self.lock:\n            return MappingProxyType(dict(self.latest))\n\n    def take_if_current(self, route):\n        with self.lock:\n            return self.latest.get(route)\n\n    def forward_to_legacy_token_lane(self, *args, **kwargs):\n        # This would silently overwrite alternate DLMM routes with same token.\n        raise RuntimeError(\'HOLD_ROUTE_KEY_REQUIRED_IN_PRICING_WORKER\')\n\n    def collision_tokens(self):\n        with self.lock:\n            pools = {}\n            for k in self.latest:\n                pools.setdefault(k.token, set()).add((k.pump_pool, k.dlmm_pool))\n            return tuple(sorted(t for t, ps in pools.items() if len(ps) > 1))\n\ndef main():\n    print(\'[MTR144] ROUTE_KEYED_QUEUE_IMPORT_PASS\')\n    print(\'[LEGACY_TOKEN_LANE] FORWARDING_BLOCKED\')\n    print(\'[CANONICAL_SCANNER] FROZEN\')\n    print(\'[PRODUCTION_CUTOVER] FALSE\')\n    print(\'[HOT_REST] NONE\')\n    print(\'[PRIVATE_KEY] NOT_USED\')\n    print(\'[SIGNING] FALSE\')\n    print(\'[BROADCAST] FALSE\')\n\nif __name__ == \'__main__\':\n    main()\n'
TEST_SOURCE = "import unittest\nfrom qseries_v2.oracle_execution.solana_atomic_executor.mtr_139_ws_warm_admission_gate import AdmissionGate\nfrom qseries_v2.oracle_execution.solana_atomic_executor.mtr_144_route_identity_latest_queue import RouteKey, RouteLatestQueue, SIZES\n\nclass Tests(unittest.TestCase):\n    def setUp(self):\n        self.now = 1000000000\n        self.g = AdmissionGate(100, clock=lambda: self.now)\n        self.q = RouteLatestQueue(self.g, lambda x: x)\n\n    def admit(self, rid, dlmm, slot=10):\n        epoch = self.g.discover(rid, 'TOKEN', 'PUMP', dlmm, ('pump_account', 'dlmm_account'))\n        self.g.mark_exact(rid, epoch)\n        self.g.mark_warm(rid, epoch)\n        self.g.mark_subscribed(rid, epoch)\n        for a in ('pump_account', 'dlmm_account'):\n            self.g.observe_ws(rid, epoch, a, slot)\n        self.g.publish(rid, epoch)\n        return epoch\n\n    def snap(self, dlmm, slot=10):\n        return {'token': 'TOKEN', 'pump_pool': 'PUMP', 'dlmm_pool': dlmm,\n                'account_slots': {'pump_account': slot, 'dlmm_account': slot},\n                'sizes': SIZES}\n\n    def test_admission_required(self):\n        self.assertFalse(self.q.offer('a', self.snap('A'), 10, self.now))\n        self.assertFalse(self.q.inventory())\n\n    def test_two_dlmm_routes_same_token_survive(self):\n        self.admit('a', 'A')\n        self.admit('b', 'B')\n        self.assertTrue(self.q.offer('a', self.snap('A'), 10, self.now))\n        self.assertTrue(self.q.offer('b', self.snap('B'), 10, self.now))\n        self.assertEqual(len(self.q.inventory()), 2)\n        self.assertEqual(self.q.collision_tokens(), ('TOKEN',))\n        self.assertEqual(self.q.take_if_current(RouteKey('TOKEN', 'PUMP', 'A')).snapshot['dlmm_pool'], 'A')\n\n    def test_reprice_same_route_requires_new_ws_generation(self):\n        epoch = self.admit('a', 'A')\n        self.assertTrue(self.q.offer('a', self.snap('A'), 10, self.now))\n        self.assertFalse(self.q.offer('a', self.snap('A'), 10, self.now))\n        self.g.observe_ws('a', epoch, 'dlmm_account', 11)\n        self.assertFalse(self.q.offer('a', self.snap('A', 11), 11, self.now))\n        self.g.publish('a', epoch)\n        fresh = self.snap('A', 11)\n        fresh['account_slots']['pump_account'] = 10\n        self.assertTrue(self.q.offer('a', fresh, 11, self.now))\n        self.assertEqual(self.q.stats['replaced'], 1)\n\n    def test_wrong_binding_rejected(self):\n        self.admit('a', 'A')\n        bad = self.snap('B')\n        with self.assertRaises(ValueError):\n            self.q.offer('a', bad, 10, self.now)\n\n    def test_stale_proof_rejected(self):\n        self.admit('a', 'A')\n        self.now += 101000000\n        self.assertFalse(self.q.offer('a', self.snap('A'), 10, self.now))\n\n    def test_legacy_token_forwarding_is_blocked(self):\n        self.admit('a', 'A')\n        with self.assertRaisesRegex(RuntimeError, 'HOLD_ROUTE_KEY_REQUIRED'):\n            self.q.forward_to_legacy_token_lane()\n\nif __name__ == '__main__':\n    unittest.main(verbosity=2)\n"
if not (PKG / 'mtr_139_ws_warm_admission_gate.py').is_file():
    raise SystemExit('[HOLD] Missing MTR-139 admission dependency')
for source in (MODULE, TEST_SOURCE):
    ast.parse(source)
TARGET.write_text(MODULE, encoding='utf-8')
TEST.write_text(TEST_SOURCE, encoding='utf-8')
print('[PASS] installed', TARGET.relative_to(ROOT))
print('[PASS] installed', TEST.name)
print('[SCOPE] ROUTE_IDENTITY_QUEUE_STAGED; canonical cutover pending')
print('[SCANNER] FROZEN')
print('[PRIVATE_KEY] NOT_USED')
print('[SIGNING] FALSE')
print('[BROADCAST] FALSE')
